import{webkit}from'playwright';
const R='abcdefghi',INIT='lnsgkgsnl/1r5b1/ppppppppp/9/9/9/PPPPPPPPP/1B5R1/LNSGKGSNL';
function sfen(ms){const b=new Map();let y=0;for(const row of INIT.split('/')){let f=9;for(const c of row){if(/\d/.test(c)){f-=+c;continue}b.set(''+f+R[y],{s:c===c.toUpperCase()?'b':'w',k:c.toUpperCase()});f--}y++}let t='b';for(const m of ms){const a=m.slice(0,2),d=m.slice(2,4),p=b.get(a);if(!p)throw Error('bad '+m);b.delete(a);b.set(d,p);t=t==='b'?'w':'b'}const rows=[];for(let r=0;r<9;r++){let z='',e=0;for(let f=9;f;f--){const p=b.get(''+f+R[r]);if(!p){e++;continue}if(e){z+=e;e=0}z+=p.s==='b'?p.k:p.k.toLowerCase()}if(e)z+=e;rows.push(z)}return rows.join('/')+' '+t+' - '+(ms.length+1)}
const cases=[['open7',sfen(['7g7f'])],['open2',sfen(['2g2f'])],['midA',sfen(['7g7f','3c3d','2g2f','8c8d','2f2e','8d8e'])],['midB',sfen(['2g2f','8c8d','2f2e','8d8e','7g7f','3c3d','6g6f','6c6d'])]];
const targets=[{i:15,n:'まり',r:1950,ms:520,max:115,min:2},{i:12,n:'あすか',r:1900,ms:470,max:125,min:2},{i:20,n:'みさとさん',r:1880,ms:430,max:135,min:2},{i:18,n:'前田慶次',r:1820,ms:380,max:145,min:3},{i:9,n:'あやなみ',r:1800,ms:340,max:155,min:3},{i:11,n:'伊達政宗',r:1750,ms:300,max:170,min:3}];
const browser=await webkit.launch({headless:true}),page=await browser.newPage({viewport:{width:390,height:844}}),errs=[];page.on('pageerror',e=>errs.push(String(e.message||e)));
try{await page.goto('http://127.0.0.1:4233/shogi-v21528/index-b-feasibility.html?x='+Date.now(),{waitUntil:'domcontentloaded',timeout:120000});await page.waitForFunction(()=>window.__B_DIAG&&window.AI_SHOGI_YANEURAOU_FUTURE&&window.AI_SHOGI_YANEURAOU_COHORT7_12&&document.querySelectorAll('#chars .ch').length===26,{timeout:120000});
const meta=await page.evaluate(()=>[...document.querySelectorAll('#chars .ch')].map((x,i)=>({i,t:x.textContent.trim()})));for(const t of targets){if(!meta[t.i]?.t.includes(t.n)||!meta[t.i]?.t.includes(String(t.r)))throw Error('identity '+JSON.stringify({t,got:meta[t.i]}))}
const rows=[];for(const [label,pos]of cases){const st=await page.evaluate(pos=>window.__B_DIAG.parse(pos),pos);for(const t of targets){const res=await page.evaluate(async({s,ms})=>window.AI_SHOGI_YANEURAOU_FUTURE.bestMove(s,{ms,multiPV:5,adaptive:false}),{s:st,ms:t.ms});const c=(res?.info?.candidates||[]).filter(x=>x?.token).sort((a,b)=>(a.rank||99)-(b.rank||99)),best=c[0];if(!best)throw Error('no candidates '+label+' '+t.n);const loss=x=>Number.isFinite(best.cp)&&Number.isFinite(x.cp)?Math.max(0,best.cp-x.cp):0;const safe=c.filter(x=>loss(x)<=t.max),pref=safe.filter(x=>(x.rank||1)>=t.min),pick=(pref[0]||safe[0]||best);rows.push({case:label,...t,best:best.token,pick:pick.token,rank:pick.rank,loss:loss(pick),depth:res?.info?.depth,nodes:res?.info?.nodes,cands:c.length});}}
const by=targets.map(t=>{const a=rows.filter(x=>x.i===t.i);return{...t,tests:a.length,nonBest:a.filter(x=>x.rank>1).length,within:a.filter(x=>x.loss<=t.max).length,meanLoss:Math.round(a.reduce((s,x)=>s+x.loss,0)/a.length),meanDepth:Math.round(a.reduce((s,x)=>s+(x.depth||0),0)/a.length),minCands:Math.min(...a.map(x=>x.cands))}}),fail=[];for(const x of by){if(x.tests!==4||x.within!==4)fail.push('loss '+x.n);if(x.nonBest<2)fail.push('diversity '+x.n);if(x.minCands<3)fail.push('candidates '+x.n)}if(errs.length)fail.push('page '+errs.join('|'));console.log('COHORT13_18_FEASIBILITY '+JSON.stringify({by,rows,fail,pageErrors:errs}));if(fail.length)throw Error(fail.join(' | '));console.log('PASS_COHORT13_18_FEASIBILITY '+JSON.stringify({by}));}finally{await browser.close()}
